  readonly parts: readonly MutablePart[];
  readonly positions: number[];
  readonly statuses: Set<number>;
  readonly contentTypes: Set<string>;
  readonly queryNames: Set<string>;
  readonly apiPath: boolean;
  jsonLike: boolean;
